dtsPropsFor.Button:
/** Visual style. @default "default" */
  variant?: "default" | "destructive" | "outline" | "secondary" | "ghost" | "link";
  /** Control size. @default "default" */
  size?: "default" | "sm" | "lg" | "icon";
  /** Render as the child element (Radix Slot) instead of a <button>. @default false */
  asChild?: boolean;
  className?: string;
  children?: React.ReactNode;
  disabled?: boolean;
  type?: "button" | "submit" | "reset";
  onClick?: React.MouseEventHandler<HTMLButtonElement>;

dtsPropsFor.Card:
/** Card is a compound: Card, CardHeader, CardTitle, CardDescription, CardContent, CardFooter. */
  className?: string;
  children?: React.ReactNode;

dtsPropsFor.Input:
/** Native <input> type. `search` and `file` get extra styling. */
  type?: React.HTMLInputTypeAttribute;
  placeholder?: string;
  value?: string;
  defaultValue?: string;
  disabled?: boolean;
  /** Marks the field invalid; adds a destructive ring + border. */
  "aria-invalid"?: boolean;
  className?: string;
  onChange?: React.ChangeEventHandler<HTMLInputElement>;

dtsPropsFor.Badge:
/** Visual style. @default "default" */
  variant?: "default" | "secondary" | "destructive" | "orange" | "success" | "accent" | "outline";
  className?: string;
  children?: React.ReactNode;

dtsPropsFor.Tabs:
/** Tabs is a compound: Tabs (root), TabsList, TabsTrigger, TabsContent (Radix Tabs). */
  /** Controlled active tab value. */
  value?: string;
  /** Uncontrolled initial active tab value. */
  defaultValue?: string;
  onValueChange?: (value: string) => void;
  orientation?: "horizontal" | "vertical";
  className?: string;
  children?: React.ReactNode;
